using namespace std;

int main() {
    long long h[2], m[2];

    for (int i = 0; i < 2; ++i)
        scanf("%lld:%lld", &h[i], &m[i]);

    h[0] -= h[1];
    m[0] -= m[1];

    if (m[0] < 0) {
        m[0] += 60;
        --h[0];
    }

    if (h[0] < 0)
        h[0] += 24;

    printf("%02lld:%02lld", h[0], m[0]);

    return 0;
}

